; [33] {$I memory.pas}
; [0] { ---------------------------------------------------------------------------
; [1]   memory.pas -- paged memory access                     K16 Pascal, Part 24 / 25
; [2]   Bodies in memory.asm.  k/OS target only.
; [3] 
; [4]   Mem[x] reads a byte from the CURRENT data page (Y3) and has no page
; [5]   selector.  This module is that same access with the page supplied
; [6]   explicitly, so a task can reach the extra pages of a multi-page run
; [7]   (a $PAGES declaration) rather than only the one it executes in.
; [8] 
; [9]       Mem[x]  ==  MemGetByte(x, SysMyPage)
; [10] 
; [11]   ---- Why the arguments are separate Words and not a record ----------------
; [12] 
; [13]   Passing a two-word record by value costs a __memcopy call at every call
; [14]   site (measured, Part 24 s3.3).  The V2 ABI puts the last three scalar
; [15]   arguments in D0/D1/D2, so every entry point here takes three or fewer and
; [16]   none of them touches the stack.  Keep it that way when adding to it.
; [17] 
; [18]   ---- Endianness: read this before using MemGetWord ------------------------
; [19] 
; [20]   K16 is little-endian and word access faults on an odd address.  Z-machine
; [21]   words are BIG-endian and sit at arbitrary byte offsets.  Those are two
; [22]   different things and they get two different routines:
; [23] 
; [24]     MemGetWord     native.  Little-endian, ofs MUST be even.  For structures
; [25]                    you lay out yourself.
; [26]     MemGetWordBE   two byte reads, hi*256+lo.  Any alignment.  For a Z-machine
; [27]                    story image, and anything else that arrived big-endian.
; [28] 
; [29]   A single routine that quietly did the big-endian thing would be wrong for
; [30]   every non-Z caller that came later, so the call site has to say which.
; [31] 
; [32]   ---- The cursor -----------------------------------------------------------
; [33] 
; [34]   MemSeek / MemNextByte / MemNextWordBE / MemTell* are the sequential fast path:
; [35]   MemNextByte is a post-increment load and a return, against MemGetByte's
; [36]   argument marshalling and address rebuild.  Z-text decoding is almost
; [37]   entirely sequential, so this is the hot path.
; [38] 
; [39]   ONE cursor, shared by every routine that uses it.  It advances with
; [40]   [XY0]+, which carries into the page byte, so walking off the end of a page
; [41]   lands correctly on the next one (verified gate-level by PAGETEST, k/OS
; [42]   Part 60).  Note that ADD X0,#2 does NOT carry -- it wraps within the page --
; [43]   which is why nothing here advances a pointer by more than one at a time.
; [44]   --------------------------------------------------------------------------- }
; [45] 
; [46] { The bodies. Resolved by the same probe as $I: the including file is
; [47]   rtl\memory.pas, so the source-directory arm finds rtl\memory.asm with no
; [48]   path needed. Kept here rather than in every caller, so a program writes one
; [49]   line -- the $I -- and gets both halves. }
; [50] {$L memory.asm}
                .INCLUDE "C:/K16 CPU/K16 Pascal/rtl/memory.asm"
; [51] 
; [52] { ---- Random access ---- }
; [53] function  MemGetByte  (ofs, page: Word): Byte;  external '__mgetb';
; [54] function  MemGetWord  (ofs, page: Word): Word;  external '__mgetw';
; [55] function  MemGetWordBE(ofs, page: Word): Word;  external '__mgetwbe';
; [56] procedure MemPutByte  (ofs, page, v: Word);     external '__mputb';
; [57] procedure MemPutWord  (ofs, page, v: Word);     external '__mputw';
; [58] 
; [59] { ---- Sequential cursor ---- }
; [60] procedure MemSeek     (ofs, page: Word);        external '__mseek';
; [61] function  MemNextByte : Byte;                   external '__mnextb';
; [62] function  MemNextWordBE: Word;                  external '__mnextwbe';
; [63] 
; [64] { Read the cursor back, so a reader can leave it and return -- restore with
; [65]   MemSeek. Two entries because the ABI has one result register. Use these
; [66]   rather than shadowing the position in the caller: one position tracked by
; [67]   two mechanisms that must agree about carry is the sys_read hazard. }
; [68] function  MemTellOfs  : Word;                   external '__mtellofs';
; [69] function  MemTellPage : Word;                   external '__mtellpage';
; [70] 
; [71] { ---- Bulk ----
; [72] 
; [73]   MemRead reads into the cursor and advances it, so loading a story image is
; [74]   MemSeek to the run's second page and one call.
; [75] 
; [76]   It chunks internally, and that is a correctness requirement rather than
; [77]   tuning: sys_read honours the destination page byte, but between sectors it
; [78]   advances only the OFFSET, with no carry.  A single kernel call whose buffer
; [79]   crossed $FFFF would wrap to offset 0 in the same page and overwrite the
; [80]   start of it -- silently, since the straddling sector itself copies
; [81]   correctly.  MemRead therefore never hands the kernel a request that reaches
; [82]   a page boundary.
; [83] 
; [84]   A short return means EOF.  $FFFF means a hard error, matching FileRead's -1. }
; [85] function  MemRead(fd, n: Word): Word;           external '__mread';
; [86] procedure MemSkip(n: Word);                     external '__mskip';
; [87] 
; [88] { MemCopyTo copies n bytes from the cursor to (dstOfs, dstPage) and advances
; [89]   the cursor by n.  Roughly four instructions per byte against twenty-five for
; [90]   the equivalent Pascal loop, which is the difference between a page copy
; [91]   being unnoticeable and being the longest phase of a program's startup.
; [92] 
; [93]   From the cursor, rather than taking a source pair, because the ABI holds
; [94]   three arguments and a five-argument form would spill to the stack -- see the
; [95]   note at the top of this file.
; [96] 
; [97]   No page-boundary chunking, and unlike MemRead that is deliberate: both
; [98]   pointers are [XYn]+, which carries into the page byte in hardware, so source
; [99]   and destination cross pages on their own.  MemRead's clamping exists only
; [100]   because sys_read will not carry.
; [101] 
; [102]   Forward copy, so overlapping regions are safe only when dst is below src.
; [103] 
; [104]   MemSum adds n bytes from the cursor as a 16-bit sum and advances the cursor.
; [105]   n is a Word, so a caller summing more than 65535 bytes calls it repeatedly
; [106]   and adds the results -- partial sums of a mod-65536 total add correctly, and
; [107]   the chunk boundary is a natural place to show progress. }
; [108] procedure MemCopyTo(dstOfs, dstPage, n: Word);  external '__mcopyto';
; [109] function  MemSum(n: Word): Word;                external '__msum';
; [110] 
; [111] { ---- Self-discovery.  No kernel support needed: Y3 is the run base, and the
; [112]   page count is a word in the task's own .COM header at $0208. ---- }
; [113] function  SysMyPage:      Word;                 external '__mypage';
; [114] function  SysMyPageCount: Word;                 external '__mypagecount';
; [115] 
; [116] { True under the Digital gate-level simulator, False under EMU.
; [117] 
; [118]   The same probe _DetectHost uses at boot: the SHL lookup ROM at $E0:$2468
; [119]   holds $2468 on Digital -- the address is the input $1234 doubled, and the
; [120]   value is $1234 shifted left, which happen to be the same number -- while EMU
; [121]   computes its lookups instead of storing them and reads back $00.
; [122] 
; [123]   Deliberately NOT read from the kernel's KOS_HOST, which is the better source
; [124]   in principle.  That is a page-$00 sysvar address hardcoded into a user
; [125]   program, and page $00 is being regionised: a stale literal would not fail
; [126]   loudly, it would read some other word and choose a target.  This probes a
; [127]   hardware property, which cannot move.
; [128] 
; [129]   $2468 is even, as MemGetWord requires. }
; [130] function SysIsDigital: Boolean;
; [131] begin
; var SysIsDigital(@RESULT)
__SysIsDigital104:                                  ; Prologue
                PUSH     X2, XY3
                LOADP    D0, Y3, [#display+2]
                SUB      X3, #2                     ; alloc 2b spill/result space
                PUSH     D0, XY3
                MOVE     D0, X3
                STOREP   D0, Y3, [#display+2]
                MOVE     X2, D0
                SUB      X3, #FRAMESPACE_SysIsDigital104; locals + concat dests
; [132]   SysIsDigital := (MemGetWord($2468, $E0) = $2468);
                MOVE     D0, X2
                ADD      D0, #2                     ; SysIsDigital
                PUSH     D0, XY3
                LOADI    D0, #9320                  ; Literal 9320
                LOADI    D1, #224
                CALL16   __mgetw
                LOADI    D1, #9320
                CMP      D0, D1
                SEQ      D0
                AND      D0, #1
                MOVE     D1, D0
                POP      D0, XY3
                STOREB   D1, [XY2+#2]               ; [frame+2]
; [133] end;
exit105:                                            ; Epilogue
                LOADP    D0, Y3, [#display+2]
                MOVE     X3, D0
                LOADB    D0, [XY3+#2]
                POP      D1, XY3
                STOREP   D1, Y3, [#display+2]
                ADD      X3, #2
                POP      D1, XY3
                MOVE     X2, D1
                RET
; [34] {$I zmem.pas}
; [0] { ---------------------------------------------------------------------------
; [1]   zmem.pas -- Z-machine story image: residency, header, addressing
; [2]                                                       K16 Pascal, Part 25 / 27
; [3] 
; [4]   Include AFTER memory.pas and files.pas. No $L of its own -- every body here
; [5]   is Pascal; the assembler half is memory.asm's.
; [6] 
; [7]   Directive names appear bare in these comments on purpose. A braced directive
; [8]   written inside a braced comment ends that comment at the INNER brace, and the
; [9]   rest of the prose is then parsed as code -- Part 24 s5.5.
; [10] 
; [11]   ---- Why almost nothing here carries a page -------------------------------
; [12] 
; [13]   Every address in the v3 header is a 16-bit BYTE address, so dynamic memory,
; [14]   static memory, the object table, the dictionary and the globals all live
; [15]   below $10000 by construction: story page 0, offset only.
; [16] 
; [17]   The second page is reached only by PACKED addresses (routines and strings,
; [18]   x2 in v3) and by the abbreviation table's WORD addresses (also x2). Hence
; [19]   ZSeekPacked and ZSeekWordAddr are the only routines here that compute a
; [20]   page, and every other entry point takes a plain Word.
; [21] 
; [22]   ---- What is deliberately NOT wrapped -------------------------------------
; [23] 
; [24]   MemNextByte / MemNextWordBE / MemTellOfs / MemTellPage are called directly
; [25]   by ztext and zexec. A ZNext that only forwarded to MemNextByte would cost
; [26]   a CALL16 and a RET on the interpreter's hottest path to buy a synonym.
; [27]   zmem owns ADDRESSING, which is genuinely different work; it does not own a
; [28]   renaming layer.
; [29] 
; [30]   ---- Endianness -----------------------------------------------------------
; [31] 
; [32]   Z words are big-endian at arbitrary offsets, so ZWord is MemGetWordBE and
; [33]   ZPutWord is TWO byte writes. MemPutWord is native little-endian and must
; [34]   never appear in this engine.
; [35]   --------------------------------------------------------------------------- }
; [36] 
; [37] const
; [38]   { ---- v3 header offsets (Standard 1.1 s11) ---- }
; [39]   ZH_VERSION  = $00;  ZH_FLAGS1   = $01;  ZH_RELEASE  = $02;
; [40]   ZH_HIMEM    = $04;  ZH_INITPC   = $06;  ZH_DICT     = $08;
; [41]   ZH_OBJECTS  = $0A;  ZH_GLOBALS  = $0C;  ZH_STATIC   = $0E;
; [42]   ZH_FLAGS2   = $10;  ZH_SERIAL   = $12;  ZH_ABBREV   = $18;
; [43]   ZH_LENGTH   = $1A;  ZH_CHECKSUM = $1C;
; [44] 
; [45]   ZHDR_SIZE   = $40;
; [46] 
; [47]   { Largest dynamic memory this build will save or restore.
; [48] 
; [49]     The Z-machine permits nearly 64 KB; every real v3 story uses a small
; [50]     fraction of it (Zork I: 11,282 bytes). The cap is what keeps every
; [51]     Quetzal chunk length inside 16 bits: CMem's worst case is 1.5 bytes out
; [52]     per byte in -- alternating zero and non-zero deltas, each zero costing a
; [53]     two-byte run -- so 32 KB in cannot exceed 48 KB out, and the whole FORM
