; [36] {$I zobj.pas}
; [0] { ---------------------------------------------------------------------------
; [1]   zobj.pas -- Z-machine v3 object table                    K16 Pascal, Part 25
; [2] 
; [3]   Include AFTER zmem.pas and ztext.pas.
; [4] 
; [5]   ---- Layout (Standard 1.1 s12), all of it inside story page 0 -------------
; [6] 
; [7]     ZObjTab + 0            31 words of property defaults, for properties 1..31
; [8]     ZObjTab + 62           object 1, then 2, ... each 9 bytes:
; [9] 
; [10]         byte 0..3          32 attribute flags, attribute 0 = bit 7 of byte 0
; [11]         byte 4             parent object number
; [12]         byte 5             sibling
; [13]         byte 6             child
; [14]         byte 7..8          byte address of this object's property table
; [15] 
; [16]   A property table is:
; [17] 
; [18]         byte 0             short name length, in WORDS
; [19]         the short name     that many words of Z-string
; [20]         properties         descending by number, each a size byte then data
; [21]         byte 0             terminator
; [22] 
; [23]   and a v3 size byte is 32*(len-1) + number, so a property holds 1..8 bytes and
; [24]   the number is 1..31. v4+ uses a two-byte form; this module is v3 only and
; [25]   will produce nonsense on a v4 story rather than pretend otherwise, which is
; [26]   what ZMemInit's version check is there to prevent.
; [27] 
; [28]   ---- Object 0 -------------------------------------------------------------
; [29] 
; [30]   Object 0 is not an object. It is the value meaning "nothing" in the parent,
; [31]   sibling and child fields, and the Standard says a program may not use it.
; [32]   Every accessor here returns 0 for it rather than reading nine bytes from
; [33]   ZObjTab + 62 - 9, which lands inside the property defaults.
; [34]   --------------------------------------------------------------------------- }
; [35] 
; [36] const
; [37]   ZO_DEFAULTS  = 62;      { 31 words of property defaults ahead of object 1 }
; [38]   ZO_ENTRY     = 9;       { bytes per object entry in v3 }
; [39]   ZO_ATTRBYTES = 4;
; [40]   ZO_PARENT    = 4;       { offsets within an entry }
; [41]   ZO_SIBLING   = 5;
; [42]   ZO_CHILD     = 6;
; [43]   ZO_PROPS     = 7;       { word: byte address of the property table }
; [44]   ZO_MAXOBJ    = 255;     { v3 object numbers are a single byte }
; [45]   ZO_MAXPROP   = 31;
; [46] 
; [47] { ---- Addressing ---------------------------------------------------------- }
; [48] 
