; [37] {$I zdict.pas}
; [0] { ---------------------------------------------------------------------------
; [1]   zdict.pas -- Z-machine v3 dictionary and input tokeniser
; [2]                                                            K16 Pascal, Part 26
; [3] 
; [4]   Include AFTER zmem.pas and ztext.pas. The ENCODER lives in ztext.pas, not
; [5]   here, so that the alphabet table has one definition -- see the note there.
; [6] 
; [7]   Directive names appear bare in these comments on purpose (Part 24 s5.5).
; [8] 
; [9]   ---- Layout (Standard 1.1 s13) --------------------------------------------
; [10] 
; [11]     ZDict + 0        byte    n = number of word separators
; [12]     ZDict + 1        n bytes ZSCII codes of the separators
; [13]     ZDict + 1 + n    byte    entry length in bytes (>= 4 in v3)
; [14]     ZDict + 2 + n    word    entry count, SIGNED
; [15]     ZDict + 4 + n    the entries
; [16] 
; [17]   Each v3 entry is four bytes of encoded text -- two words, bit 15 set on the
; [18]   second -- followed by (entry_length - 4) bytes the game owns and the
; [19]   interpreter never reads.
; [20] 
; [21]   ---- The count is signed, and it matters ----------------------------------
; [22] 
; [23]   A NEGATIVE count means the dictionary is UNSORTED and must be searched
; [24]   linearly; the magnitude is the entry count. Infocom and Inform both emit
; [25]   sorted dictionaries in practice (Zork I release 119 is sorted, verified),
; [26]   so a binary search on an unsorted table would work almost always and fail
; [27]   on somebody's homebrew story with no symptom but a word that will not parse.
; [28]   Both paths are here.
; [29] 
; [30]   ---- Separators are WORDS, not just delimiters ----------------------------
; [31] 
; [32]   Zork I's separators are '.', ',' and '"' -- and those are dictionary
; [33]   entries 2, 3 and 8. So a separator terminates the token before it AND is
; [34]   emitted as a one-character token of its own. Discarding them, which is what
; [35]   a plain "split on delimiters" tokeniser does, loses `say "hello"' and the
; [36]   multi-command period.
; [37]   --------------------------------------------------------------------------- }
; [38] 
; [39] const
; [40]   { Inclusive upper bounds -- array bounds must be constant identifiers. }
; [41]   ZD_SEPTOP = 15;         { at most 16 separators; v3 stories use 3 }
; [42] 
; [43]   { Parse-buffer entry layout, 4 bytes per word. }
; [44]   ZD_PE_ADDR = 0;         { word: dictionary byte address, 0 = not found }
; [45]   ZD_PE_LEN  = 2;         { byte: letters in the token }
; [46]   ZD_PE_POS  = 3;         { byte: position of the token in the text buffer }
; [47]   ZD_PE_SIZE = 4;
; [48] 
; [49] var
; [50]   ZDSepCount : Word;
; [51]   ZDSeps     : array[0..ZD_SEPTOP] of Word;
