; [38] {$I zdis.pas}
; [0] { ---------------------------------------------------------------------------
; [1]   zdis.pas -- Z-machine v3 instruction decoder                K16 Pascal, Part 26
; [2] 
; [3]   Include AFTER zmem.pas and ztext.pas.
; [4] 
; [5]   Decodes the instruction at the cursor and leaves the cursor immediately past
; [6]   it -- past the operands, the store byte, the branch bytes and any inline
; [7]   string. Nothing is executed and nothing is written to story memory.
; [8] 
; [9]   ---- THE CURSOR IS THE PC -------------------------------------------------
; [10] 
; [11]   This is the whole reason the module is this small. A branch target is
; [12]   `where the cursor is now, plus offset, minus 2', evaluated at the point the
; [13]   branch data has just been consumed. There is no instruction-length
; [14]   arithmetic anywhere, and instruction length is the single most error-prone
; [15]   quantity in this format -- operands are 1 or 2 bytes depending on a type
; [16]   field, the store byte is present for some opcodes only, the branch is 1 or 2
; [17]   bytes depending on a bit inside itself, and print/print_ret carry an inline
; [18]   string of unbounded length.
; [19] 
; [20]   ---- The three forms (Standard 1.1 s4.3) ----------------------------------
; [21] 
; [22]     b >= $C0    VARIABLE form. Bit 5 selects the operand COUNT, not the form:
; [23]                 clear -> 2OP, set -> VAR. Opcode number is b and $1F. A type
; [24]                 byte follows, four 2-bit fields, high pair first, and the
; [25]                 first $03 (omitted) ends the list.
; [26] 
; [27]     $80..$BF    SHORT form. (b shr 4) and 3 is the operand type; $03 means no
; [28]                 operand at all, so the instruction is 0OP. Opcode is b and $0F.
; [29] 
; [30]     b < $80     LONG form, always 2OP. Opcode is b and $1F. Bit 6 gives the
; [31]                 type of the first operand and bit 5 the second, but only as
; [32]                 one bit each: clear = small constant, set = variable. A long
; [33]                 form can never carry a large constant.
; [34] 
; [35]   Operand types: 0 large constant (2 bytes), 1 small constant (1 byte),
; [36]   2 variable (1 byte), 3 omitted.
; [37] 
; [38]   ---- Branches -------------------------------------------------------------
; [39] 
; [40]   One byte, or two. Bit 7 is the POLARITY -- branch when the condition
; [41]   matches this bit, so `branch on false' is an encoding, not a separate
; [42]   opcode. Bit 6 set means the offset is the remaining 6 bits, unsigned, 0..63.
; [43]   Bit 6 CLEAR means a 14-bit SIGNED offset spanning both bytes, and it must be
; [44]   sign-extended from bit 13 -- the commonest way to get this wrong is to treat
; [45]   it as unsigned and silently never branch backwards.
; [46] 
; [47]   Offsets 0 and 1 are not offsets. They mean `return false' and `return true'.
; [48] 
; [49]   ---- What still needs a table ---------------------------------------------
; [50] 
; [51]   Which opcodes store a result, and which branch, cannot be derived from the
; [52]   encoding -- they are properties of the opcode. Both are case statements
; [53]   below rather than data tables, because the compiler has no procedure
; [54]   pointers and a case is what it generates well.
; [55]   --------------------------------------------------------------------------- }
; [56] 
; [57] const
; [58]   { Operand counts }
; [59]   ZC_0OP = 0;  ZC_1OP = 1;  ZC_2OP = 2;  ZC_VAR = 3;
; [60] 
; [61]   { Operand types }
; [62]   ZOT_LARGE = 0;  ZOT_SMALL = 1;  ZOT_VAR = 2;  ZOT_OMIT = 3;
; [63] 
; [64]   ZD_OPTOP = 3;           { at most 4 operands in v3 }
; [65] 
; [66]   { Instruction flags, held in ZDFlags and indexed (cls shl 5) or op. }
; [67]   ZDF_BRANCH = $01;
; [68]   ZDF_STORE  = $02;
; [69] 
; [70]   { Branch dispositions }
; [71]   ZBR_OFFSET = 0;         { normal: jump by ZIBrOfs }
; [72]   ZBR_RFALSE = 1;
; [73]   ZBR_RTRUE  = 2;
; [74] 
; [75] var
; [76]   ZIClass  : Word;                        { ZC_* }
; [77]   ZIOpcode : Word;                        { opcode number within its class }
; [78]   ZINOps   : Word;
; [79]   ZIOpT    : array[0..ZD_OPTOP] of Word;
; [80]   ZIOpV    : array[0..ZD_OPTOP] of Word;
; [81] 
; [82]   ZIStore  : Boolean;
; [83]   ZIStoreV : Word;
; [84] 
; [85]   ZIBranch : Boolean;
; [86]   ZIBrOn   : Boolean;                     { branch when the test equals this }
; [87]   ZIBrWhat : Word;                        { ZBR_* }
; [88]   ZIBrOfs  : Word;                        { signed 14-bit, held as a Word }
; [89] 
; [90]   ZIText   : Boolean;                     { an inline string was consumed }
; [91] 
; [92]   { Inline strings are always CONSUMED -- the cursor must end up past them
; [93]     either way -- but whether they are also PRINTED depends on the caller.
; [94]     zdistest decodes without executing and wants silence; zexec is running
; [95]     print/print_ret and wants the text. Decoding to the buffer and printing
; [96]     that afterwards is not an option: ZTBuf caps at 255 characters and Zork's
; [97]     room descriptions are longer. }
; [98]   ZDPrintText : Boolean;
; [99] 
; [100]   { Byte address of the instruction just decoded, as (page-relative, offset).
; [101]     Captured before anything is consumed so a caller can report it. }
; [102]   ZIAtOfs  : Word;
; [103]   ZIAtPage : Word;
; [104] 
; [105]   { Byte address of the BRANCH DATA of the instruction just decoded, captured
; [106]     the same way. Meaningful only when ZIBranch.
; [107] 
; [108]     This exists for `save'. Quetzal s5.8.1 requires a v3 save file to record
; [109]     the address of the save instruction's branch bytes -- not the instruction,
; [110]     and not what follows it -- because that is where a restore resumes: it
; [111]     seeks there, decodes the branch it finds, and takes it as though the save
; [112]     had succeeded. Since the cursor IS the PC and the decoder has already run
; [113]     past the branch data by the time zexec sees the opcode, the address has to
; [114]     be captured on the way through. }
; [115]   ZIBrAtOfs  : Word;
; [116]   ZIBrAtPage : Word;
; [117] 
; [118]   { Flag byte of the instruction just decoded, read once from ZDFlags so the
; [119]     store and branch tests below share a single table access. }
; [120]   ZIFlags    : Word;
; [121] 
; [122]   { Does this opcode store, does it branch: a function of (class, opcode)
; [123]     only, so a table rather than a search. Built by ZDisInit, which
; [124]     ZExecInit calls. 128 bytes -- classes are 0..3 and no class exceeds 32
; [125]     opcodes, so (cls shl 5) or op cannot collide. }
; [126]   ZDFlags    : array[0..127] of Byte;
; [127] 
; [128] { ---- Opcode properties --------------------------------------------------- }
; [129] 
; [130] { ---- Instruction flags ---------------------------------------------------
; [131] 
; [132]   Whether an opcode stores a result and whether it branches depends only on
; [133]   (class, opcode), so it is a table lookup, not a search.
; [134] 
; [135]   It used to be two functions, each a chain of up to twelve or-ed
; [136]   comparisons, both called on every decode -- roughly two dozen comparisons
; [137]   and two calls per Z-instruction to answer two static questions. Unless the
; [138]   compiler short-circuits `or', every one of those comparisons evaluated
; [139]   every time, including for the opcode that matched first.
; [140] 
; [141]   Index is (cls shl 5) or op. Classes are 0..3 and no class has more than 32
; [142]   opcodes, so the two never collide and the table is 128 bytes.
; [143] 
; [144]   ZDisInit MUST be called before the first ZDecode. ZExecInit does it. Any
; [145]   other program that decodes -- zdistest -- has to call it too, and a table
; [146]   left at zero does not fault: it decodes every instruction as neither
; [147]   storing nor branching, which desynchronises the stream and produces
; [148]   confident nonsense. }
; [149] 
; [150] procedure ZDMark(cls, op, f: Word);
; [151] var
; [152]   i: Word;
; [153] begin
; var cls(+6), op(+4), f(+2), i(@l_ZDMark_i)
__ZDMark457:                                        ; Prologue
                PUSH     X2, XY3
                MOVE     D3, D0
                LOADP    D0, Y3, [#display+2]
                SUB      X3, #6                     ; alloc 6b spill/result space
                PUSH     D0, XY3
                MOVE     D0, X3
                STOREP   D0, Y3, [#display+2]
                MOVE     X2, D0
                STORED   D2, [XY2+#2]               ; spill D2->[frame+2]
                STORED   D1, [XY2+#4]               ; spill D1->[frame+4]
                STORED   D3, [XY2+#6]               ; spill D3->[frame+6]
                SUB      X3, #FRAMESPACE_ZDMark457  ; locals + concat dests
; [154]   i := (cls shl 5) or op;
                LOADD    D0, [XY2+#6]               ; [frame+6]
                SHL      D0, #5
                PUSH     D0, XY3
                LOADD    D0, [XY2+#4]               ; [frame+4]
                MOVE     D1, D0
                POP      D0, XY3
                OR       D0, D1
                STOREP   D0, Y3, [#l_ZDMark_i]      ; paged dest
