                POP      D0, XY3
                OR       D0, D1
                MOVE     D1, D0
                POP      X0, XY3                    ; pointer into X
                MOVE     Y0, Y3
                STOREB   D1, [XY0]
; [156] end;
exit458:                                            ; Epilogue
                LOADP    D0, Y3, [#display+2]
                MOVE     X3, D0
                POP      D0, XY3
                STOREP   D0, Y3, [#display+2]
                ADD      X3, #6
                POP      D1, XY3
                MOVE     X2, D1
                RET
