; [234] 
; [235] { ---- Branch data ---------------------------------------------------------
; [236] 
; [237]   Split out of ZDecode in Part 27 because `restore' has to decode a branch on
; [238]   its own: Quetzal hands back a PC pointing at the branch bytes of the SAVE
; [239]   instruction that wrote the file, and the restoring interpreter must decode
; [240]   what it finds there and take it as true (s5.8.1). That is a branch decode
; [241]   with no instruction in front of it.
; [242] 
; [243]   Duplicating these twenty lines in zsave was the alternative, and the
; [244]   sign-extension below is exactly the kind of detail that would have been
; [245]   copied once and then fixed in only one of the two places. }
; [246] 
; [247] procedure ZDDecodeBranch;
; [248] var
; [249]   b1, b2: Word;
; [250] begin
; var b1(@l_ZDDecodeBranch_b1), b2(@l_ZDDecodeBranch_b2)
