; [39] {$I zstate.pas}
; [0] { ---------------------------------------------------------------------------
; [1]   zstate.pas -- Z-machine stacks and call frames             K16 Pascal, Part 27
; [2] 
; [3]   Include AFTER zdis and BEFORE zsave and zexec.
; [4] 
; [5]   Declarations only. Every line here was in zexec.pas up to Part 26 and moved
; [6]   out unchanged in Part 27, with one addition (ZFArgs).
; [7] 
; [8]   ---- Why this file exists -------------------------------------------------
; [9] 
; [10]   Ordering, and nothing else. This compiler is single pass, so a routine must
; [11]   be declared before it is called. zsave needs the frame arrays; zexec needs
; [12]   to call zsave from ZExec0OP. That forces zsave to sit between the state and
; [13]   zexec, and the state therefore has to come out of zexec into its own file.
; [14] 
; [15]   The alternative -- a forward declaration, or a nested include -- buys
; [16]   nothing and hides the dependency. This way the include order in zork.pas
; [17]   reads as the dependency graph.
; [18] 
; [19]   ---- Why the call stack is an explicit array ------------------------------
; [20] 
; [21]   This compiler allocates locals STATICALLY -- they appear as l_Routine_name
; [22]   in the GLOBALS region -- so a recursive Pascal routine overwrites its own
; [23]   caller's locals. The Z-machine's call stack therefore cannot be the Pascal
; [24]   call stack, and ZFrames below is not a design preference, it is forced.
; [25]   Part 27 collects on the parenthesis Part 26 left here: `save' has to
; [26]   serialise it, and an explicit array is trivial to walk.
; [27]   --------------------------------------------------------------------------- }
; [28] 
; [29] const
; [30]   { Inclusive upper bounds -- bounds must be constant identifiers. }
; [31]   ZS_TOP    = 1023;       { Z-machine evaluation stack, words }
; [32]   ZF_TOP    = 63;         { call frames }
; [33]   ZL_COUNT  = 15;         { locals per routine, v3 maximum }
; [34]   ZLOC_TOP  = 959;        { (ZF_TOP + 1) * ZL_COUNT - 1, written out }
; [35] 
; [36]   ZRETVAR_NONE = $0100;   { no store variable; outside the 0..255 range }
; [37] 
; [38] var
; [39]   ZStack   : array[0..ZS_TOP] of Word;
; [40]   ZSP      : Word;                        { next free slot }
; [41] 
; [42]   ZFPCOfs  : array[0..ZF_TOP] of Word;    { return cursor }
; [43]   ZFPCPage : array[0..ZF_TOP] of Word;
; [44]   ZFFloor  : array[0..ZF_TOP] of Word;    { ZSP on entry }
; [45]   ZFNLoc   : array[0..ZF_TOP] of Word;
; [46]   ZFRetVar : array[0..ZF_TOP] of Word;
; [47] 
; [48]   { Number of arguments the call supplied. Recorded solely so `save' can
; [49]     write Quetzal's `arguments supplied' byte (s4.3.4) honestly rather than
; [50]     zero-filling it. Nothing in a v3 interpreter reads it back -- the opcode
; [51]     that needs it, check_arg_count, is v5 -- but a save file is a public
; [52]     artifact and another interpreter may one day care. }
; [53]   ZFArgs   : array[0..ZF_TOP] of Word;
; [54] 
; [55]   ZLocals  : array[0..ZLOC_TOP] of Word;  { frame * ZL_COUNT + n }
; [56]   ZFP      : Word;                        { current frame index }
; [57] 
; [58]   { ZFP * ZL_COUNT, maintained incrementally rather than recomputed.
; [59] 
; [60]     ZLIdx used to do the multiply on every local variable read AND write --
; [61]     the most frequent operation in the interpreter, and one most Z-opcodes
; [62]     perform at least once. K16 has no 16x16 multiply in hardware; the ROM ALU
; [63]     cannot table a 32-bit result, so it is a shift-add routine of roughly
; [64]     sixteen iterations.
; [65] 
; [66]     ZFP only ever moves by one, in ZDoCall and ZDoReturn, so the product can
; [67]     be carried alongside it for an add and a subtract. Every assignment to
; [68]     ZFP must have a matching adjustment here -- there are exactly four, in
; [69]     ZExecInit, ZDoCall, ZDoReturn and ZQCommitStks, plus the reset in
; [70]     ZQRestart.
; [71] 
; [72]     The one place it is still computed the honest way is ZQCommitStks, which
; [73]     rebuilds ZFP wholesale from a save file and runs once per restore. }
; [74]   ZFBase   : Word;
; [40] {$I zsave.pas}
; [0] { ---------------------------------------------------------------------------
; [1]   zsave.pas -- Quetzal save, restore and restart             K16 Pascal, Part 27
; [2] 
; [3]   Include AFTER zmem, ztext, zdis and zstate, and BEFORE zexec.
; [4] 
; [5]   Writes and reads the Quetzal 1.4 save format (Martin Frost, 03-Nov-97), so
; [6]   a save written here restores under Frotz and a save written by Frotz
; [7]   restores here. That interoperability is not a courtesy: a round trip
; [8]   through our own code is equally happy if the frames are written wrongly and
; [9]   read back wrongly in the same way, and only a second implementation can
; [10]   tell the difference.
; [11] 
; [12]   ---- What a saved game actually is ----------------------------------------
; [13] 
; [14]   Three things, and nothing else:
; [15] 
; [16]     1. dynamic memory     bytes 0 .. ZStatic-1   (11,282 in Zork I)
; [17]     2. the stacks         call frames and the evaluation stack
; [18]     3. the PC
; [19] 
; [20]   Everything above ZStatic is read-only for the lifetime of the story and is
; [21]   reconstructed from the story file, never stored. Infocom's own interpreters
; [22]   saved the same three things in private layouts; Quetzal is that content in
; [23]   an IFF wrapper, with a story-identity check and optional compression.
; [24] 
; [25]   ---- The two extra pages --------------------------------------------------
; [26] 
; [27]   ZPgOrig holds dynamic memory exactly as it came off disk, captured before
; [28]   ZSetHeaderFlags stamps the interpreter's own bits. It is the XOR baseline
; [29]   CMem is defined against (s3.2) and the source `restart' copies back.
; [30] 
; [31]   ZPgStage is where a restore is assembled. Nothing a restore reads touches
; [32]   the running game until every chunk has been read and checked, so a
; [33]   truncated or corrupt save file is a clean refusal rather than a half-loaded
; [34]   machine. Dynamic memory stages at offset 0; the Stks chunk stages at
; [35]   ZSTK_STAGE, above ZDYN_MAX, so the two cannot collide.
; [36] 
; [37]   ---- Lengths are counted, never backpatched -------------------------------
; [38] 
; [39]   files.pas has no FileSeek, so a chunk length cannot be written as zero and
; [40]   fixed up afterwards. Every length is therefore computed before it is
; [41]   written: IFhd is a constant 13, Stks is arithmetic over the frames, and
; [42]   CMem runs its encoder twice through ZQCMem -- once with emit False to
; [43]   count, once with emit True to write. Two passes over the same deterministic
; [44]   loop cannot disagree; a backpatch that silently failed could.
; [45] 
; [46]   ---- Signedness -----------------------------------------------------------
; [47] 
; [48]   ZQBN and ZQBI are Integer, not Word, and deliberately so. FileRead returns
; [49]   -1 on error, and a buffer count that has to be compared against -1 and
; [50]   against 512 in the same routine must be signed throughout or one of the two
; [51]   comparisons picks the wrong branch (Part 24 s5.1).
; [52]   --------------------------------------------------------------------------- }
; [53] 
; [54] const
; [55]   ZQ_BUFTOP  = 511;       { I/O buffer, inclusive upper bound }
; [56]   ZQ_BUFN    = 512;
; [57] 
; [58]   { Where the Stks chunk stages inside ZPgStage. Above ZDYN_MAX, so dynamic
; [59]     memory (staged at offset 0) can never reach it. }
; [60]   ZSTK_STAGE = $8000;
; [61] 
; [62]   { Largest Stks chunk this build can hold:
; [63]       (ZF_TOP+1) * 8            frame headers        512
; [64]       (ZLOC_TOP+1) * 2          locals              1920
; [65]       (ZS_TOP+1) * 2            evaluation stack    2048
; [66]                                                     ---- 4480 }
; [67]   ZSTK_MAX   = 4480;
; [68] 
; [69]   { IFF identifiers, as the two big-endian words they are on the wire.
; [70]     Compared numerically rather than as strings: four bytes in, two CMPs,
; [71]     and no string machinery on a path that runs before anything is trusted. }
; [72]   ZQ_FORM_HI = $464F;  ZQ_FORM_LO = $524D;        { 'FORM' }
; [73]   ZQ_IFZS_HI = $4946;  ZQ_IFZS_LO = $5A53;        { 'IFZS' }
; [74]   ZQ_IFHD_HI = $4946;  ZQ_IFHD_LO = $6864;        { 'IFhd' }
; [75]   ZQ_CMEM_HI = $434D;  ZQ_CMEM_LO = $656D;        { 'CMem' }
; [76]   ZQ_UMEM_HI = $554D;  ZQ_UMEM_LO = $656D;        { 'UMem' }
; [77]   ZQ_STKS_HI = $5374;  ZQ_STKS_LO = $6B73;        { 'Stks' }
; [78] 
; [79]   ZQ_IFHD_LEN = 13;     { s5.4.2 -- odd, so it carries a pad byte (s5.7) }
; [80] 
; [81]   { Quetzal frame flags byte, 000pvvvv (s4.3.2) }
; [82]   ZQ_FLAG_DISCARD = $10;
; [83]   ZQ_FLAG_NLOC    = $0F;
; [84] 
