; [41] {$I zexec.pas}
; [0] { ---------------------------------------------------------------------------
; [1]   zexec.pas -- Z-machine v3 execution                 K16 Pascal, Part 26 / 27
; [2] 
; [3]   Include AFTER zmem, ztext, zobj, zdict, zdis, zstate and zsave.
; [4] 
; [5]   The decoder is zdis.pas and is already verified against ztools' txd over
; [6]   20,968 instructions in Zork I, II and III. This module is the half that
; [7]   runs them: variables, frames, branches and the opcode bodies.
; [8] 
; [9]   ---- Where the stack and the frames went ----------------------------------
; [10] 
; [11]   Into zstate.pas, unchanged, in Part 27. zsave needs them and zexec calls
; [12]   zsave, so in a single-pass compiler the declarations have to precede both.
; [13]   Nothing about their meaning changed; ZFArgs was added alongside them.
; [14] 
; [15]   ---- The cursor IS the PC -------------------------------------------------
; [16] 
; [17]   Carried over from zdis: the memory cursor is the program counter, so a
; [18]   branch target is `where the cursor is now, plus offset, minus 2'. Only
; [19]   call, return and branch ever move it explicitly. ZPCRel does the page
; [20]   carry, which is the one piece of arithmetic here that must handle the
; [21]   story's second page.
; [22] 
; [23]   ---- Indirect variable references -----------------------------------------
; [24] 
; [25]   store, inc, dec, inc_chk, dec_chk, load and pull take a variable NUMBER as
; [26]   their first operand and act on that variable IN PLACE. For variable 0 that
; [27]   means the top of the stack is read or written WITHOUT being popped or
; [28]   pushed (Standard 1.1 s6.3.4). Using the ordinary variable path for these
; [29]   silently corrupts the stack, and the symptom appears in some unrelated
; [30]   routine much later -- ZVarGetInd / ZVarSetInd exist for exactly this.
; [31] 
; [32]   ---- Signedness -----------------------------------------------------------
; [33] 
; [34]   Z-machine values are 16-bit SIGNED where it matters: jl, jg, add, sub, mul,
; [35]   div, mod, inc_chk, dec_chk, print_num and jump's offset. Word is unsigned
; [36]   here, so the comparisons go through ZLT (a bias-by-$8000 trick) and the
; [37]   divides through sign-magnitude. Getting this wrong makes a room's object
; [38]   count of -1 compare as 65535 and the game wanders.
; [39]   --------------------------------------------------------------------------- }
; [40] 
; [41] var
; [42]   ZOp      : array[0..ZD_OPTOP] of Word;  { evaluated operand values }
; [43] 
; [44]   ZQuit    : Boolean;
; [45]   ZFault   : Boolean;
; [46]   ZRndSeed : Word;
; [47] 
; [48]   ZInBuf   : String;                      { one input line }
; [49]   ZTmpS    : String;                      { shared scratch: a String LOCAL
; [50]                                             costs a 256-byte frame block at
; [51]                                             every call site (Part 24 s5.2) }
; [52]   ZPCSOfs  : Word;                        { PC save slot -- see ZPCSave }
; [53]   ZPCSPage : Word;
; [54]   ZDisc    : Word;                        { sink for results that must be
; [55]                                             consumed but not used }
; [56] 
; [57]   { Instruction trace. zdistest verified the decoder's BOUNDARIES and opcode
; [58]     classification, but never its operand VALUES -- it printed only address,
; [59]     class and opcode number. A bad operand fetch passes that test silently,
; [60]     so the trace prints the evaluated operands too and is diffed against the
; [61]     same trace produced by a host-side model. Zork I reaches its first sread
; [62]     in 407 instructions, so a couple of hundred lines localise anything in
; [63]     the startup path. }
; [64]   ZTraceMax : Word;                       { 0 = off }
; [65]   ZTraceN   : Word;
; [66] 
; [67] { ---- Faults -------------------------------------------------------------- }
; [68] 
; [69] { Loud, not silent. A Z-machine that keeps going after a stack overflow
; [70]   produces output that looks almost right, which is far worse to diagnose
; [71]   than a stop. }
; [72] procedure ZDie(var msg: String);
; [73] begin
; var msg(+2)
__ZDie753:                                          ; Prologue
                PUSH     X2, XY3
                MOVE     D3, D0
                LOADP    D0, Y3, [#display+2]
