                PUSH     D0, XY3
                MOVE     D0, X3
                STOREP   D0, Y3, [#display+2]
                MOVE     X2, D0
                STORED   D3, [XY2+#2]               ; spill D3->[frame+2]
                SUB      X3, #FRAMESPACE_ZDie753    ; locals + concat dests
; [74]   ZOutNewLine;
                CALL16   __ZOutNewLine210
; [75]   Write('[z-machine fault: ');
