                STOREPB  D0, Y3, [#g_ZQuit]         ; paged dest
; [80] end;
exit754:                                            ; Epilogue
                LOADP    D0, Y3, [#display+2]
                MOVE     X3, D0
                POP      D0, XY3
                STOREP   D0, Y3, [#display+2]
